content.content:
1	"use client";
2	
3	import { useRouter } from "next/navigation";
4	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
5	import { ArrowUp, Paperclip, Mic, X, Gift, Sparkles } from "lucide-react";
6	import { motion, useReducedMotion } from "framer-motion";
7	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
8	import { SIGNUP_GRANT } from "@/lib/credits";
9	
10	// The rotating gradient inside each glow clip MUST be a square that is
11	// larger than the clip's diagonal, or it stops covering the clip partway
12	// through its own rotation and the ring visibly vanishes and returns on a
13	// loop. (The previous `inset-[-50%]` made it 2x the clip in BOTH axes —
14	// e.g. 1372x296 for this wide composer. Rotated 90deg that occupies
15	// 296x1372: only 296px wide, far short of the ~686px the clip needs
16	// covered. Hence "the glow keeps disappearing.")
17	//
18	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
19	// always exceeds the diagonal. Centering uses margins rather than a
20	// translate because `transform` is owned by the rotation keyframes and a
21	// transform in the animation would override any translate set here —
22	// percentage margins (all sides, per spec) resolve against the containing
23	// block's WIDTH, so -100% on both axes lands the square's center exactly
24	// on the clip's center.
25	const SPIN_SQUARE: React.CSSProperties = {
26	  position: "absolute",
27	  left: "50%",
28	  top: "50%",
29	  width: "200%",
30	  aspectRatio: "1",
31	  marginLeft: "-100%",
32	  marginTop: "-100%",
33	};
34	
35	const SUGGESTIONS = [
36	  "A portfolio site for a freelance photographer",
37	  "A landing page for my SaaS product",
38	  "A website for a neighborhood coffee shop",
39	  "A booking page for my consulting practice",
40	];
41	
42	// Downscale + re-encode client-side so a phone photo doesn't blow past
43	// sessionStorage's per-origin quota (or the tokens it costs Claude to look
44	// at it) — a reference image only needs to be legible, not full-resolution.
45	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
46	  const bitmap = await createImageBitmap(file);
47	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
48	  const w = Math.round(bitmap.width * scale);
49	  const h = Math.round(bitmap.height * scale);
50	  const canvas = document.createElement("canvas");
51	  canvas.width = w;
52	  canvas.height = h;
53	  const ctx = canvas.getContext("2d");
54	  if (!ctx) throw new Error("canvas unsupported");
55	  ctx.drawImage(bitmap, 0, 0, w, h);
56	  return canvas.toDataURL("image/jpeg", quality);
57	}
58	
59	// The Web Speech API has no types in TypeScript's DOM lib, so this is a
60	// minimal hand-written shim covering exactly the surface used below —
61	// narrower than the real spec on purpose, so it can't quietly drift into
62	// asserting support for members this component never touches.
63	type SpeechRecognitionAlternativeLike = { readonly transcript: string };
64	type SpeechRecognitionResultLike = {
65	  readonly length: number;
66	  readonly [index: number]: SpeechRecognitionAlternativeLike;
67	};
68	type SpeechRecognitionEventLike = {
69	  readonly results: {
70	    readonly length: number;
71	    readonly [index: number]: SpeechRecognitionResultLike;
72	  };
73	};
74	type SpeechRecognitionLike = {
75	  continuous: boolean;
76	  interimResults: boolean;
77	  lang: string;
78	  start: () => void;
79	  stop: () => void;
80	  onresult: ((e: SpeechRecognitionEventLike) => void) | null;
81	  onend: (() => void) | null;
82	  onerror: (() => void) | null;
83	};
84	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
85	
86	// Narrowed locally rather than via `declare global`: augmenting Window would
87	// collide with the (differently-shaped) definitions any future TS DOM lib
88	// ships for this API.
89	type SpeechCapableWindow = {
90	  SpeechRecognition?: SpeechRecognitionCtor;
91	  webkitSpeechRecognition?: SpeechRecognitionCtor;
92	};
93	
94	function getSpeechRecognition(): SpeechRecognitionCtor | null {
95	  if (typeof window === "undefined") return null;
96	  const w = window as unknown as SpeechCapableWindow;
97	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
98	}
99	
100	// Feature detection is *external* state: it is unknowable while rendering on
101	// the server, and rendering the mic button in the server HTML would be a
102	// hydration mismatch. useSyncExternalStore is the sanctioned way to express
103	// that — getServerSnapshot() feeds both SSR and the hydration render, and
104	// React re-reads getSnapshot() only once hydration has finished. Support
105	// never changes within a page's life, so subscribe is a no-op.
106	const NEVER_CHANGES = () => () => {};
107	const readSpeechSupported = () => getSpeechRecognition() !== null;
108	const speechUnsupportedOnServer = () => false;
109	
110	export function PromptHero() {
111	  const router = useRouter();
112	  const reduced = useReducedMotion();
113	  const [value, setValue] = useState("");
114	  const [focused, setFocused] = useState(false);
115	  const [image, setImage] = useState<string | null>(null);
116	  const [listening, setListening] = useState(false);
117	  const speechSupported = useSyncExternalStore(
118	    NEVER_CHANGES,
119	    readSpeechSupported,
120	    speechUnsupportedOnServer,
121	  );
122	  const [enhanceSupported, setEnhanceSupported] = useState(false);
123	  const [enhancing, setEnhancing] = useState(false);
124	  // The prompt as typed, kept only while an enhanced spec is on screen — this
125	  // is what "Revert" restores, and its presence is what tells the composer it
126	  // is currently showing a spec rather than a one-liner.
127	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
128	  const [enhanceError, setEnhanceError] = useState<string | null>(null);
129	  const fileInputRef = useRef<HTMLInputElement>(null);
130	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
131	  const baseValueRef = useRef("");
132	
133	  // /api/enhance is auth-gated, and most people meeting this hero are signed
134	  // out — so the button appears only once we know it would work, the same way
135	  // the mic waits on feature detection above. Failing closed is the point:
136	  // an affordance that 401s on click is worse than no affordance.
137	  useEffect(() => {
138	    let alive = true;
139	    fetch("/api/auth/me")
140	      .then((res) => res.json())
141	      .then((body) => {
142	        if (alive && body?.user) setEnhanceSupported(true);
143	      })
144	      .catch(() => {});
145	    return () => {
146	      alive = false;
147	    };
148	  }, []);
149	
150	  async function enhance() {
151	    const text = value.trim();
152	    if (!text || enhancing) return;
153	
154	    setEnhancing(true);
155	    setEnhanceError(null);
156	    try {
157	      const res = await fetch("/api/enhance", {
158	        method: "POST",
159	        headers: { "Content-Type": "application/json" },
160	        // Always the ORIGINAL one-liner, never a spec we already produced —
161	        // enhancing an enhancement compounds invention instead of adding
162	        // detail, and the round trip would drift further from what was asked.
163	        body: JSON.stringify({ prompt: enhancedFrom ?? text }),
164	      });
165	      const body = await res.json().catch(() => ({}));
166	      if (!res.ok || !body?.spec) throw new Error(body?.error ?? "Couldn't expand that.");
167	      setEnhancedFrom(enhancedFrom ?? text);
168	      setValue(body.spec);
169	    } catch (err) {
170	      // Nothing is destroyed on failure: `value` still holds what they typed,
171	      // and the build button beside this was never disabled.
172	      setEnhanceError(err instanceof Error ? err.message : "Couldn't expand that.");
173	    } finally {
174	      setEnhancing(false);
175	    }
176	  }
177	
178	  function revert() {
179	    if (enhancedFrom === null) return;
180	    setValue(enhancedFrom);
181	    setEnhancedFrom(null);
182	    setEnhanceError(null);
183	  }
184	
185	  function submit() {
186	    const text = value.trim();
187	    if (!text) return;
188	    try {
189	      sessionStorage.setItem(PENDING_PROMPT_KEY, text);
190	      if (image) sessionStorage.setItem(PENDING_PROMPT_IMAGE_KEY, image);
191	      else sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
192	    } catch {}
193	    router.push("/signup");
194	  }
195	
196	  async function onPickImage(e: React.ChangeEvent<HTMLInputElement>) {
197	    const file = e.target.files?.[0];
198	    e.target.value = "";
199	    if (!file || !file.type.startsWith("image/")) return;
200	    try {
201	      setImage(await downscaleImage(file));
202	    } catch {}
203	  }
204	
205	  function toggleListening() {
206	    const Ctor = getSpeechRecognition();
207	    if (!Ctor) return;
208	
209	    if (listening) {
210	      recognitionRef.current?.stop();
211	      return;
212	    }
213	
214	    const rec = new Ctor();
215	    rec.continuous = true;
216	    rec.interimResults = true;
217	    rec.lang = "en-US";
218	    baseValueRef.current = value ? value.trim() + " " : "";
219	
220	    rec.onresult = (e: SpeechRecognitionEventLike) => {
221	      let transcript = "";
222	      for (let i = 0; i < e.results.length; i++) transcript += e.results[i][0].transcript;
223	      setValue((baseValueRef.current + transcript).trimStart());
224	    };
225	    rec.onend = () => setListening(false);
226	    rec.onerror = () => setListening(false);
227	
228	    recognitionRef.current = rec;
229	    rec.start();
230	    setListening(true);
231	  }
232	
233	  useEffect(() => () => recognitionRef.current?.stop(), []);
234	
235	  return (
236	    <div className="relative mx-auto w-full max-w-2xl">
237	      {/* Free-credits badge — the first thing a visitor should register
238	          about pricing, before they've even typed anything. Sits above the
239	          glow/composer group entirely (not inside its relative wrapper) so
240	          the glow below hugs just the box, not the badge too. */}
241	      <div className="mb-4 flex justify-center">
242	        <span className="inline-flex items-center gap-1.5 rounded-full border border-neutral-200/70 bg-white/60 px-3.5 py-1.5 text-xs font-medium text-neutral-600 backdrop-blur-md dark:border-white/10 dark:bg-white/[0.05] dark:text-neutral-300">
243	          <Gift size={13} style={{ color: "var(--accent)" }} />
244	          Get {SIGNUP_GRANT} free credits — enough for a real site and a few edits
245	        </span>
246	      </div>
247	
248	      {/* This inner wrapper is sized to exactly the composer box — the glow
249	          layers below position with -inset-N relative to IT specifically,
250	          not the outer component (which also holds the badge and suggestion
251	          chips), so the glow hugs just the box, never the whole component. */}
252	      <div className="relative">
253	      {/* The glow — a Gemini-style "chasing light" ring, rebuilt with only
254	          plain `transform: rotate()` + `overflow: hidden` clipping — no
255	          @property, no CSS masking (dropped after those didn't visibly
256	          work even in a fresh, verified non-cached browser). Two layers:
257	          a thin bright one (-inset-[7px]) and a soft blurred halo
258	          (-inset-[22px]). Deliberately NOT the page's big ambient .aura
259	          blobs (Aura.tsx), a separate, much larger, static effect.
260	
261	          The blur lives on the CLIP element, not on the rotating child.
262	          That ordering matters: filters apply AFTER the element (and its
263	          overflow:hidden clipping) is rendered, so the blur softens the
264	          clip's hard outer cutoff and lets the light bleed beyond the
265	          clip's bounds — a real falloff. With the blur on the child
266	          instead, the clip's crisp edge survives and the result reads as
267	          a chunky solid border rather than a glow.
268	
269	          Each layer's blur radius therefore wants to be comparable to or
270	          larger than its own inset, so the band never looks like a hard
271	          stripe. Opacities are deliberately well under 1 (see
272	          glow-fade-in-a/-b) — at full strength the brand colors read as a
273	          saturated ring instead of ambient light.
274	
275	          Each layer is a STATIC outer clipper (glow-clip-*, overflow:
276	          hidden, never transforms) containing one OVERSIZED inner
277	          rotator (glow-spin-*, ~2x the clipper's size via inset:-50%,
278	          centered). Only the inner rotator spins — being oversized, its
279	          corners sweeping outside a same-sized box (the original "wide
280	          rectangle rotated as a rigid body swings outside its footprint"
281	          bug) never matters, since the static outer box clips them away
282	          at every angle. The opaque composer sitting on top (z-10) covers
283	          the rotator's entire interior on its own, leaving only the outer
284	          few px visible as a ring — no masking needed for that either.
285	
286	          Opacity is fixed, not keyed off `focused` — an earlier version
287	          dimmed on blur, which read as "disappearing." The composer's own
288	          border/shadow below is the right place for a focus affordance;
289	          this ambient ring stays constant.
290	
291	          Entrance: fade+scale in once via the glow-fade-in-a/-b keyframes
292	          on the outer clipper (globals.css) — plain CSS, not a
293	          framer-motion `whileInView`.
294	
295	          NO NEGATIVE Z-INDEX HERE — this was the "it appears for a moment
296	          on load, then is gone for good" bug. PromptHero is wrapped in
297	          <Reveal>, which animates opacity 0 -> 1. An element with opacity
298	          BETWEEN 0 and 1 establishes a stacking context, which kept these
299	          layers painting above the page background while the reveal ran.
300	          The moment opacity reached exactly 1 that stacking context was
301	          destroyed, and `-z-10` dropped the layers behind the root page
302	          div's opaque bg-white / dark:bg-neutral-950 — invisible, forever.
303	          Instead the layers now sit at the default level (painting above
304	          the page background) and the composer is lifted above THEM with
305	          z-10, which needs no stacking-context trickery to hold. */}
306	      <div aria-hidden className="glow-clip-a pointer-events-none absolute -inset-[3px] overflow-hidden rounded-[1.9rem] blur-[5px]">
307	        <div
308	          className="glow-spin-a"
309	          style={{
310	            ...SPIN_SQUARE,
311	            // Stops are pushed into distinct quadrants (rather than the
312	            // near-adjacent pink/coral/orange run they used to be) so the
313	            // colour visibly travels around the box as this rotates —
314	            // closely-spaced hues just blur into one flat pink.
315	            background:
316	              "conic-gradient(#f72570 0deg, #a33dff 90deg, #ff9868 180deg, #ff6b67 270deg, #f72570 360deg)",
317	          }}
318	        />
319	      </div>
320	      <div aria-hidden className="glow-clip-b pointer-events-none absolute -inset-[14px] overflow-hidden rounded-[2.4rem] blur-[22px]">
321	        <div
322	          className="glow-spin-b"
323	          style={{
324	            ...SPIN_SQUARE,
325	            background:
326	              "conic-gradient(from 180deg, #a33dff 0deg, #f72570 90deg, #ff9868 180deg, #ff6b67 270deg, #a33dff 360deg)",
327	          }}
328	        />
329	      </div>
330	
331	      {/* The glass composer. Opaque enough that the animated ring behind it
332	          (see above) reads as a halo around the box, not a wash bleeding
333	          through onto the text — earlier versions were translucent enough
334	          that the strong glow behind showed straight through onto the
335	          placeholder/input text. Still picks up a faint frosted quality from
336	          backdrop-blur, just not at the cost of legibility. */}
337	      <div
338	        className="relative z-10 overflow-hidden rounded-[1.75rem] bg-white/95 backdrop-blur-2xl backdrop-saturate-150 transition-colors duration-300 dark:bg-neutral-950/95"
339	        style={{
340	          // No focus-driven glow here — the animated ring behind the box is
341	          // the only glow, and a second one on focus fought with it. Focus
342	          // is still signalled (it must be, for keyboard users) but with a
343	          // quiet border shift instead.
344	          border: `1.5px solid ${
345	            focused
346	              ? "color-mix(in srgb, white 45%, var(--accent) 55%)"
347	              : "color-mix(in srgb, white 75%, var(--accent) 25%)"
348	          }`,
349	          boxShadow: "var(--sh-s), inset 0 1px 0 rgba(255,255,255,0.5)",
350	        }}
351	      >
352	        {image && (
353	          <div className="flex items-center gap-2 px-6 pt-4">
354	            <div className="relative h-12 w-12 overflow-hidden rounded-lg border border-black/10 dark:border-white/10">
355	              {/* eslint-disable-next-line @next/next/no-img-element */}
356	              <img src={image} alt="Attached reference" className="h-full w-full object-cover" />
357	              <button
358	                type="button"
359	                onClick={() => setImage(null)}
360	                aria-label="Remove attached image"
361	                className="absolute right-0.5 top-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-black/60 text-white"
362	              >
363	                <X size={10} strokeWidth={3} />
364	              </button>
365	            </div>
366	            <span className="text-xs text-neutral-500 dark:text-neutral-400">Reference image attached</span>
