/**
 * The prompt wizard's data model and its one real job: turning a handful of
 * answers into a PROMPT.
 *
 * ## Why this file emits text and not a config object
 *
 * The wizard's output is a plain-English prompt that lands in a textarea the
 * user can read, edit and delete half of. It is never a hidden state blob that
 * /api/generate reads. Three reasons, in order of weight:
 *
 *   1. There is exactly one build path. The raw composer is the default entry
 *      point and always will be; if the wizard emitted a config, we would have
 *      two paths to test, debug and eval, and the second one would rot.
 *   2. The user stays in control. They can see what the wizard decided on their
 *      behalf. A config object cannot offer that.
 *   3. lib/templates.ts already proves the shape. The 23 starter prompts are
 *      exactly what an expert-written wizard output looks like — audience,
 *      tone, ordered sections, bracketed placeholders, link-outs instead of
 *      forms. So the wizard's job is to help someone produce one of those, not
 *      to invent a parallel format.
 *
 * ## Zero model calls
 *
 * Everything here is local string work. /api/enhance is auth-gated and rate
 * limited per user id, and most people meeting the wizard have no account —
 * an affordance that 401s on click is worse than no affordance. So assembly is
 * synchronous, offline, and identical signed in or out.
 *
 * Enhance is deliberately NOT part of the wizard flow afterwards either. The
 * wizard's output is already a structured brief in Enhance's own house style
 * (Audience / tone / ordered sections / bracketed placeholders), and it is
 * routinely longer than lib/enhance.ts's MAX_PROMPT_CHARS — /api/enhance
 * answers exactly that case with "That's already detailed enough to build".
 * The wizard assembles; Enhance polishes a one-liner. Neither duplicates the
 * other, and neither gets to overwrite the palette the user picked.
 *
 * ## Colour is hexes, never adjectives
 *
 * "Warm and modern" is the instruction that produces the same three sites every
 * time. Every look direction below resolves to a real preset in
 * lib/assets/patterns.ts, and the emitted prompt carries that preset's id AND
 * its literal stops, plus a pointer at the find_assets tool the builder already
 * has. That makes the choice unambiguous for the model and auditable for us.
 */

import { getGradient, type GradientPreset } from "./assets/patterns";
import { PENDING_PROMPT_KEY } from "./pending-prompt";
import { getTemplate, TEMPLATES, type Template, type TemplateCategory } from "./templates";

// ---------------------------------------------------------------------------
// Step 1 — what and who
// ---------------------------------------------------------------------------

/**
 * The eighth chip. Not a TemplateCategory, because it deliberately maps to no
 * template — someone whose business is not on the list must not be forced to
 * claim it is.
 */
export const SOMETHING_ELSE = "Something else";

/** Kept short on purpose: this becomes the subject of the opening sentence. */
export const MAX_NAME_CHARS = 80;
/** One line, not an essay. The composer is where a long brief belongs. */
export const MAX_WHAT_CHARS = 240;

export type WizardAnswers = {
  /** A TemplateCategory, SOMETHING_ELSE, or null while nothing is chosen. */
  category: TemplateCategory | typeof SOMETHING_ELSE | null;
  /** The closest template inside that category — the skeleton for the prompt. */
  templateId: string | null;
  businessName: string;
  whatYouDo: string;
  /** A LOOK_DIRECTIONS id, or null when step 2 was skipped. */
  lookId: string | null;
};

export const EMPTY_ANSWERS: WizardAnswers = {
  category: null,
  templateId: null,
  businessName: "",
  whatYouDo: "",
  lookId: null,
};

/** The templates a category chip should offer as "closest match". */
export function templatesForCategory(category: WizardAnswers["category"]): Template[] {
  if (!category || category === SOMETHING_ELSE) return [];
  return TEMPLATES.filter((t) => t.category === category);
}

// ---------------------------------------------------------------------------
// Step 2 — six pre-rendered design directions
// ---------------------------------------------------------------------------

/**
 * One of six directions on the look picker.
 *
 * A rendered preview here would mean a real build (120-550 credits), so these
 * are drawn purely in CSS from presets that already exist — no model call, no
 * network, instant. The user still ends up choosing concrete hexes rather than
 * an adjective, which is the part that actually matters.
 */
export type LookDirection = {
  /** Stable — it ends up in analytics and in the assembled prompt. */
  id: string;
  name: string;
  /** One line, shown on the card and repeated into the prompt. */
  blurb: string;
  /** Resolved from GRADIENTS in lib/assets/patterns.ts. */
  gradient: GradientPreset;
  /** How the typography reads, in the words the prompt will use. */
  typography: string;
  /** How much room the layout takes, in the words the prompt will use. */
  density: string;
  /** Two words for the card. Same idea as `density`, without the sentence. */
  densityLabel: string;
  /**
   * The heading stack the preview card renders its own name in, so the card
   * demonstrates the direction rather than describing it. System stacks only:
   * the sandbox CSP sets no font-src, so a generated site has no web fonts and
   * a preview promising one would be a lie.
   */
  headingFont: string;
  headingWeight: number;
  headingTracking: string;
};

type LookDef = Omit<LookDirection, "gradient"> & { gradientId: string };

// Deliberately one direction per gradient FAMILY (warm, cool, neutral, nature,
// pastel, vivid) rather than six variations on a theme — the picker's value is
// spread, not choice. Note what is absent: nothing here defaults to
// indigo/violet, which is the palette an unconstrained model reaches for
// regardless of subject.
const LOOK_DEFS: LookDef[] = [
  {
    id: "warm-rustic",
    name: "Warm and rustic",
    blurb: "Earthy and hand-made — clay tones, serif headings, room to breathe.",
    gradientId: "terracotta",
    typography:
      "serif headings from the system serif stack (ui-serif, Georgia, serif) over a plain sans body, set large and unhurried",
    density: "roomy — a long vertical rhythm, roughly one idea per screen, and generous whitespace",
    densityLabel: "Roomy",
    headingFont: "ui-serif, Georgia, serif",
    headingWeight: 600,
    headingTracking: "-0.01em",
  },
  {
    id: "clean-clinical",
    name: "Clean and clinical",
    blurb: "Orderly and precise — cool teal, tight sans type, everything on a grid.",
    gradientId: "teal-fade",
    typography:
      "the system sans throughout at tight tracking, moderate sizes, hierarchy carried by weight rather than by scale",
    density: "compact — an obvious grid, even spacing, nothing oversized",
    densityLabel: "Compact",
    headingFont: "ui-sans-serif, system-ui, sans-serif",
    headingWeight: 600,
    headingTracking: "-0.02em",
  },
  {
    id: "bold-editorial",
    name: "Bold and editorial",
    blurb: "Magazine energy — near-black, oversized headlines, hairline rules.",
    gradientId: "ink",
    typography:
      "oversized system-sans headlines at very tight tracking, hairline rules, small uppercase labels with wide letter-spacing",
    density: "spacious but high-contrast — big type, wide margins, few elements per section",
    densityLabel: "High contrast",
    headingFont: "ui-sans-serif, system-ui, sans-serif",
    headingWeight: 700,
    headingTracking: "-0.04em",
  },
  {
    id: "fresh-natural",
    name: "Fresh and natural",
    blurb: "Green and open — humanist type, soft corners, plenty of air.",
    gradientId: "forest",
    typography:
      "humanist sans at comfortable sizes with generous line height, and softly rounded corners on cards and buttons",
    density: "airy — wide gutters, soft edges, nothing pressed against an edge",
    densityLabel: "Airy",
    headingFont: "ui-sans-serif, system-ui, sans-serif",
    headingWeight: 600,
    headingTracking: "-0.015em",
  },
  {
    id: "soft-elegant",
    name: "Soft and elegant",
    blurb: "Quiet and refined — pale tones, light serif, whitespace doing the work.",
    gradientId: "blush",
    typography:
      "light serif headings (ui-serif, Georgia, serif) at restrained sizes, with small uppercase labels at wide letter-spacing",
    density: "whitespace-led — very generous margins, smaller type, nothing crowded",
    densityLabel: "Whitespace-led",
    headingFont: "ui-serif, Georgia, serif",
    headingWeight: 400,
    headingTracking: "0.01em",
  },
  {
    id: "bright-energetic",
    name: "Bright and energetic",
    blurb: "Loud and fast — lime and yellow, heavy sans, flat blocks of colour.",
    gradientId: "citrus",
    typography:
      "heavy system-sans headings with big jumps between sizes, uppercase where it earns the emphasis",
    density: "dense and punchy — flat blocks of colour, tight sections, little idle space",
    densityLabel: "Dense",
    headingFont: "ui-sans-serif, system-ui, sans-serif",
    headingWeight: 800,
    headingTracking: "-0.03em",
  },
];

/**
 * The six directions, with their gradient preset resolved.
 *
 * flatMap rather than map + `!`: a typo'd preset id drops one card instead of
 * throwing at module load and taking a marketing page down with it.
 */
export const LOOK_DIRECTIONS: LookDirection[] = LOOK_DEFS.flatMap(({ gradientId, ...rest }) => {
  const gradient = getGradient(gradientId);
  return gradient ? [{ ...rest, gradient }] : [];
});

export function getLook(id: string): LookDirection | undefined {
  return LOOK_DIRECTIONS.find((l) => l.id === id);
}

// ---------------------------------------------------------------------------
// Assembly
// ---------------------------------------------------------------------------

/**
 * The skeleton for "Something else", and for anyone who skipped step 1.
 *
 * Written in the same voice as lib/templates.ts and to the same limits, so the
 * generic path inherits the same guardrails the 23 hand-written prompts carry:
 * no backend, no fake forms, no photography, bracketed placeholders for every
 * fact only the owner knows.
 */
const GENERIC_SKELETON = `Build a one-page website for [your business name].

Audience: [who you are trying to reach]. Tone: [how you want to come across] — specific and human rather than corporate.

Sections in this order:
1. Hero — the name, one line saying what this is and who it is for, and a single primary call to action.
2. What we do — three or four short blocks, each with a heading and a line or two.
3. About — a short paragraph in a real voice about who is behind this.
4. The practical details — [your location], [your opening hours], [your prices] — laid out so they are readable at a glance.
5. Footer with contact details and [your social links].

Leave every fact you cannot know as an obvious bracketed placeholder — [your address], [your phone number], [your prices] — instead of inventing something plausible.

There is no backend, so do not build a contact, booking or signup form. The calls to action are a mailto: link to [your email], a tel: link to [your phone number], and [link to the service you already use] where one is needed.

I have no photographs to supply, so carry the design with typography, colour, texture and inline SVG rather than empty image frames. Responsive down to 380px, and include a dark mode.`;

function clean(value: string, max: number): string {
  return value.trim().replace(/\s+/g, " ").slice(0, max).trim();
}

/** "a bakery in Leeds." -> "a bakery in Leeds" — we supply the punctuation. */
function stripTrailingPunctuation(value: string): string {
  return value.replace(/[.!,;:—–-]+$/, "").trim();
}

/**
 * The first line of every starter prompt is written to stand alone as a summary
 * ("Build a one-page website for [your cafe's name], …") — TemplateCard already
 * relies on that. So it is the one line safe to rewrite with the user's own
 * facts, and doing so is what turns a template into *their* brief.
 *
 * Three cases, and none of them invents anything:
 *   - name + description : write our own opener from both.
 *   - name only          : substitute it for the first bracketed token on the
 *                          template's own first line, keeping the rest of that
 *                          line's hints ("in [your city]") intact.
 *   - neither            : leave the template's first line exactly as written.
 *
 * The name-only case has one known rough edge: the wedding template opens with
 * "[name one] and [name two]", so a name substituted there leaves a stray
 * second bracket. That is a visible bracket, not an invented fact, and the
 * review step is a textarea — the user deletes it. Preferred over a per-template
 * substitution table that would drift the moment a template is edited.
 */
function openingLine(a: WizardAnswers, skeletonFirstLine: string): string {
  const name = clean(a.businessName, MAX_NAME_CHARS);
  const what = stripTrailingPunctuation(clean(a.whatYouDo, MAX_WHAT_CHARS));

  if (what) {
    return `Build a one-page website for ${name || "[your business name]"} — ${what}.`;
  }
  if (name) {
    const substituted = skeletonFirstLine.replace(/\[[^\]]*\]/, name);
    // Only trust the substitution if it actually found a bracket.
    if (substituted !== skeletonFirstLine) return substituted;
    return `Build a one-page website for ${name}.`;
  }
  return skeletonFirstLine;
}

/**
 * The block that makes the look choice binding.
 *
 * Note what it does NOT say: no adjective stands alone. The preset id, the
 * literal stops and the angle all travel, plus an instruction to pull the exact
 * source through find_assets (which lib/agent.ts already exposes) rather than
 * improvising hexes that merely resemble the swatch the user clicked.
 */
function visualDirection(look: LookDirection): string {
  const g = look.gradient;
  return [
    "Visual direction — I chose this, so build to it rather than picking your own:",
    `- Look: ${look.name}. ${look.blurb}`,
    `- Accent palette: ${g.id} (${g.colors.join(" to ")}, ${g.angle}deg). Use find_assets with the query "${g.id}" to pull the exact gradient source, and derive the rest of the palette from those hexes. Do not substitute a different colour, and do not fall back to indigo or violet.`,
    `- Typography: ${look.typography}.`,
    `- Density: ${look.density}.`,
  ].join("\n");
}

/**
 * The whole wizard, as one string.
 *
 * Deterministic and synchronous: the same answers always produce the same
 * prompt, which is what makes the paired eval fixtures on the board possible
 * later, and what lets the review step re-derive the text after an edit is
 * reverted.
 */
export function assemblePrompt(a: WizardAnswers): string {
  const template = a.templateId ? getTemplate(a.templateId) : undefined;
  const skeleton = template?.prompt ?? GENERIC_SKELETON;

  const lines = skeleton.split("\n");
  const first = lines[0] ?? "";
  const body = lines.slice(1).join("\n").trim();

  const look = a.lookId ? getLook(a.lookId) : undefined;

  return [openingLine(a, first), body, look ? visualDirection(look) : ""]
    .filter(Boolean)
    .join("\n\n")
    .trim();
}

/** True once there is anything in the prompt beyond the untouched skeleton. */
export function hasAnswers(a: WizardAnswers): boolean {
  return Boolean(
    a.category || a.templateId || a.lookId || a.businessName.trim() || a.whatYouDo.trim(),
  );
}

// ---------------------------------------------------------------------------
// Carrying the prompt through the auth wall
// ---------------------------------------------------------------------------

/**
 * A hard ceiling on what the wizard is allowed to put into sessionStorage.
 *
 * sessionStorage is roughly 5MB per origin and lib/pending-prompt.ts already
 * spends a chunk of it on a downscaled reference image. An assembled prompt is
 * 1.5-3KB, so this cap is nowhere near binding today — it exists so that the
 * budget is a decision rather than an accident when the deferred brand step
 * (logo, pasted site content) starts wanting room next to it. Anything over the
 * cap is truncated rather than dropped: losing what someone told us at the auth
 * wall is the exact failure destinationAfterAuth() exists to prevent.
 */
export const MAX_CARRIED_PROMPT_CHARS = 12_000;

/**
 * Hand the prompt to the existing pending-prompt mechanism — the same one the
 * home-page composer and the template gallery use. Deliberately not a second
 * route into a build: signup and login already show the pending prompt back,
 * their submit handlers already call destinationAfterAuth(), and the project
 * Editor already picks it up on mount.
 *
 * Returns false if storage is unavailable (private mode, blocked cookies) so
 * the caller can say so instead of navigating into an empty composer.
 */
export function stashPrompt(prompt: string): boolean {
  const text = prompt.trim().slice(0, MAX_CARRIED_PROMPT_CHARS);
  if (!text) return false;
  try {
    sessionStorage.setItem(PENDING_PROMPT_KEY, text);
    return true;
  } catch {
    return false;
  }
}

input.old_string:
try {
  sessionStorage.setItem(PENDING_PROMPT_KEY, text);
  return true;
} catch {
  return false;
}

input.new_string:
try {
  sessionStorage.setItem(PENDING_PROMPT_KEY, text);
  // A reference image attached on the home page earlier in this session would
  // otherwise ride along into a build that never asked for one. The wizard
  // has no image path of its own yet (the logo / reference-screenshot step is
  // deliberately not built), so it always clears this.
  sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
  return true;
} catch {
  return false;
}

input.content:
"use client";

import { Check } from "lucide-react";
import { LOOK_DIRECTIONS, type LookDirection } from "@/lib/wizard";

/**
 * Step 2 — six design directions, rendered entirely in CSS.
 *
 * A rendered preview of the real thing would mean six actual builds, which is
 * roughly 720-3300 credits before anyone has agreed to anything. These cost
 * nothing: each card is a gradient band straight out of lib/assets/patterns.ts,
 * the direction's own heading stack demonstrating itself, and the literal
 * hexes. No model call, no network, no waiting.
 *
 * A real fieldset/legend + radio group, not a row of aria-pressed buttons: the
 * choice is single-select, so arrow-key navigation, the "3 of 6" announcement
 * and a genuine <label> per option all come for free. Same idiom as the
 * category filter in components/templates/TemplateGallery.tsx.
 *
 * NO TEXT SITS ON A GRADIENT anywhere here. The bands are decorative and
 * aria-hidden; every word is on the card's own surface. White-on-gradient fails
 * contrast badly (1.81:1 at worst against the brand gradient) and these
 * catalogue gradients — blush and citrus especially — are lighter still.
 */
export function LookPicker({
  value,
  onChange,
}: {
  value: string | null;
  onChange: (id: string) => void;
}) {
  return (
    <fieldset>
      <legend className="text-sm font-medium">Pick a direction</legend>
      <p className="mt-1.5 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
        Each one is a real palette from Kodely&apos;s asset catalogue, so your build gets these
        exact colours rather than an interpretation of an adjective. Skip it and Kodely chooses.
      </p>

      <div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {LOOK_DIRECTIONS.map((look) => (
          <LookCard
            key={look.id}
            look={look}
            checked={value === look.id}
            onSelect={() => onChange(look.id)}
          />
        ))}
      </div>
    </fieldset>
  );
}

function LookCard({
  look,
  checked,
  onSelect,
}: {
  look: LookDirection;
  checked: boolean;
  onSelect: () => void;
}) {
  const { gradient } = look;

  return (
    // <label> only accepts phrasing content, so every wrapper below is a span
    // set to display:block rather than a div — a div here would be invalid HTML
    // even though browsers forgive it.
    <label className="block cursor-pointer">
      <input
        type="radio"
        name="wizard-look"
        value={look.id}
        checked={checked}
        onChange={onSelect}
        className="peer sr-only"
      />
      <span className="block overflow-hidden rounded-2xl border border-black/10 bg-white/60 transition-colors hover:border-black/25 peer-checked:border-neutral-900 peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-white/[0.02] dark:hover:border-white/30 dark:peer-checked:border-white">
        <span
          aria-hidden
          className="relative block h-16"
          style={{ backgroundImage: gradient.css }}
        >
          {checked && (
            <span className="absolute right-2 top-2 flex h-5 w-5 items-center justify-center rounded-full bg-white text-neutral-900 shadow-sm">
              <Check size={12} strokeWidth={3} />
            </span>
          )}
        </span>

        <span className="block p-4">
          {/* The name is set in the direction's own heading stack, so the card
              shows the typographic idea instead of only naming it. */}
          <span
            className="block text-lg leading-tight"
            style={{
              fontFamily: look.headingFont,
              fontWeight: look.headingWeight,
              letterSpacing: look.headingTracking,
            }}
          >
            {look.name}
          </span>
          <span className="mt-1.5 block text-xs leading-relaxed text-neutral-600 dark:text-neutral-400">
            {look.blurb}
          </span>

          <span className="mt-3 flex flex-wrap items-center gap-1.5">
            {gradient.colors.map((hex) => (
              <span
                key={hex}
                className="inline-flex items-center gap-1 rounded-full border border-black/10 py-0.5 pl-0.5 pr-2 font-mono text-[10px] text-neutral-600 dark:border-white/10 dark:text-neutral-400"
              >
                <span
                  aria-hidden
                  className="inline-block h-3 w-3 rounded-full"
                  style={{ background: hex }}
                />
                {hex}
              </span>
            ))}
          </span>

          <span className="mt-2.5 block text-[10px] font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400">
            {look.densityLabel} · {gradient.name}
          </span>
        </span>
      </span>
    </label>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, ArrowRight, RotateCcw, Sparkles } from "lucide-react";
import { destinationAfterAuth } from "@/lib/pending-prompt";
import { TEMPLATE_CATEGORIES } from "@/lib/templates";
import {
  assemblePrompt,
  EMPTY_ANSWERS,
  hasAnswers,
  MAX_NAME_CHARS,
  MAX_WHAT_CHARS,
  SOMETHING_ELSE,
  stashPrompt,
  templatesForCategory,
  type WizardAnswers,
} from "@/lib/wizard";
import { LookPicker } from "./LookPicker";

/**
 * The prompt wizard.
 *
 * ## It is a side door, never a gate
 *
 * The raw composer on the home page is and stays the default: nothing here
 * blocks it, nothing here renders on it, and a returning user never sees this
 * unless they ask for it. Everything below is skippable — the two question
 * screens each carry a Skip, and "Skip to the prompt" on either of them jumps
 * straight to the review with whatever has been answered so far. Abandoning
 * halfway is a productive action, not a loss.
 *
 * ## What is deliberately NOT here
 *
 * The plan's third screen — logo upload, importing your current site, and a
 * reference site — is absent rather than disabled. Each of those needs a
 * decision this pass is not making (out-of-band logo injection, SSRF controls
 * behind a separate egress service, a provenance rule for imported facts), and
 * a greyed-out field implying "coming soon" is a promise this code cannot keep.
 *
 * ## Zero model calls
 *
 * Assembly is local string work in lib/wizard.ts. There is no /api/enhance call
 * here and there should not be one: that route is auth-gated and rate limited
 * per user id, and most people meeting this wizard are signed out.
 */

const STEPS = [
  { id: "what", label: "What and who" },
  { id: "look", label: "Pick a look" },
  { id: "review", label: "Your prompt" },
] as const;

const LAST = STEPS.length - 1;

export function PromptWizard({
  signedIn,
  creditEstimate,
}: {
  signedIn: boolean;
  /** From estimateCredits("create") on the server — lib/credits.ts pulls in Prisma. */
  creditEstimate: { low: number; high: number };
}) {
  const router = useRouter();
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<WizardAnswers>(EMPTY_ANSWERS);
  /** Non-null once the review textarea has been touched. This is what Revert throws away. */
  const [edited, setEdited] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const headingRef = useRef<HTMLHeadingElement>(null);
  /** Skip the focus move on first paint — nobody asked to be sent anywhere yet. */
  const mounted = useRef(false);

  const assembled = useMemo(() => assemblePrompt(answers), [answers]);
  const promptText = edited ?? assembled;
  const matches = templatesForCategory(answers.category);

  // Moving between steps swaps the whole panel, so without this a keyboard or
  // screen-reader user is left focused on a button that no longer means what it
  // did. The sr-only status region below announces the change; this puts the
  // caret where the new content starts.
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      return;
    }
    headingRef.current?.focus();
  }, [step]);

  /**
   * Any change to an answer invalidates a hand-edit of the assembled prompt —
   * silently keeping the old text would mean the palette they just changed
   * never reaches the build. Dropping the edit is the honest failure: the
   * review step is right there and the edit was one screen ago.
   */
  function update(patch: Partial<WizardAnswers>) {
    setAnswers((prev) => ({ ...prev, ...patch }));
    setEdited(null);
  }

  function pickCategory(category: WizardAnswers["category"]) {
    const first = templatesForCategory(category)[0];
    update({ category, templateId: first?.id ?? null });
  }

  async function build() {
    if (starting) return;
    const text = promptText.trim();
    if (!text) return;

    setStarting(true);
    setError(null);

    // Hand off through the SAME pending-prompt mechanism the composer and the
    // template gallery use, rather than inventing a second route into a build.
    // Signed out: /signup shows the prompt back and its submit handler calls
    // destinationAfterAuth(). Signed in: we call it directly.
    if (!stashPrompt(text)) {
      setStarting(false);
      setError(
        "Your browser is blocking session storage, so the prompt can't travel with you. Copy it somewhere safe first, or try a normal (non-private) window.",
      );
      return;
    }

    if (!signedIn) {
      router.push("/signup");
      return;
    }

    // Returns "/dashboard" if project creation fails, including a session that
    // expired since this page rendered — the prompt stays in sessionStorage
    // either way, so nothing is lost. `starting` is deliberately left set:
    // every branch navigates, and a locked button stops a double-click
    // creating two projects.
    const dest = await destinationAfterAuth();
    router.push(dest);
    router.refresh();
  }

  return (
    <div className="mx-auto w-full max-w-3xl">
      {/* Step changes are a whole-panel swap with no page navigation, so they
          are invisible to assistive tech unless announced. */}
      <p role="status" className="sr-only">
        {`Step ${step + 1} of ${STEPS.length}: ${STEPS[step].label}.`}
      </p>

      <div className="rounded-2xl border border-black/10 bg-white/60 p-6 backdrop-blur-sm sm:p-8 dark:border-white/10 dark:bg-white/[0.02]">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p
            aria-hidden
            className="text-[11px] font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400"
          >
            Step {step + 1} of {STEPS.length} · {STEPS[step].label}
          </p>
          <div aria-hidden className="flex items-center gap-1.5">
            {STEPS.map((s, i) => (
              <span
                key={s.id}
                className={`h-1.5 rounded-full transition-all ${
                  i === step
                    ? "w-6 bg-neutral-900 dark:bg-white"
                    : i < step
                      ? "w-1.5 bg-neutral-900/40 dark:bg-white/40"
                      : "w-1.5 bg-black/10 dark:bg-white/15"
                }`}
              />
            ))}
          </div>
        </div>

        {step === 0 && (
          <WhatStep
            headingRef={headingRef}
            answers={answers}
            matches={matches}
            onPickCategory={pickCategory}
            onUpdate={update}
          />
        )}

        {step === 1 && (
          <section className="mt-6">
            <h2
              ref={headingRef}
              tabIndex={-1}
              className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
            >
              Pick a look
            </h2>
            <div className="mt-5">
              <LookPicker value={answers.lookId} onChange={(lookId) => update({ lookId })} />
            </div>
          </section>
        )}

        {step === 2 && (
          <ReviewStep
            headingRef={headingRef}
            promptText={promptText}
            edited={edited}
            onEdit={setEdited}
            onRevert={() => setEdited(null)}
            creditEstimate={creditEstimate}
            signedIn={signedIn}
            starting={starting}
            error={error}
            onBuild={build}
          />
        )}

        {/* ── Navigation ─────────────────────────────────────────────────── */}
        <div className="mt-8 flex flex-col gap-3 border-t border-black/10 pt-6 sm:flex-row sm:items-center sm:justify-between dark:border-white/10">
          <div className="flex items-center gap-3">
            {step > 0 && (
              <button
                type="button"
                onClick={() => setStep((s) => s - 1)}
                className="inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium text-neutral-600 transition-colors hover:bg-black/5 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
              >
                <ArrowLeft size={14} aria-hidden />
                Back
              </button>
            )}
            {step < LAST && (
              <button
                type="button"
                onClick={() => setStep(LAST)}
                className="rounded-lg px-3 py-2 text-sm text-neutral-500 underline underline-offset-4 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:text-white"
              >
                Skip to the prompt
              </button>
            )}
          </div>

          {step < LAST && (
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => setStep((s) => s + 1)}
                className="rounded-lg px-3 py-2 text-sm font-medium text-neutral-600 transition-colors hover:bg-black/5 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
              >
                Skip this step
              </button>
              <button
                type="button"
                onClick={() => setStep((s) => s + 1)}
                className="group inline-flex items-center justify-center gap-2 rounded-lg bg-neutral-900 px-5 py-2.5 text-sm font-medium text-white transition-colors hover:bg-neutral-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:bg-white dark:text-neutral-900 dark:hover:bg-neutral-200"
              >
                Next
                <ArrowRight
                  size={14}
                  aria-hidden
                  className="transition-transform group-hover:translate-x-0.5"
                />
              </button>
            </div>
          )}
        </div>
      </div>

      {/* The way out. It is never a dead end: "Skip to the prompt" above hands
          back everything answered so far, and this link leaves for the plain
          box, which is the default entry point and always was. */}
      <p className="mt-5 text-center text-xs text-neutral-500 dark:text-neutral-400">
        {hasAnswers(answers) && step < LAST ? (
          <>Would rather just type it? Skip to the prompt above, or </>
        ) : (
          <>Would rather just type it? </>
        )}
        <Link
          href="/"
          className="underline underline-offset-4 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:hover:text-white"
        >
          go back to the plain box
        </Link>
        .
      </p>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step 1 — what and who
// ---------------------------------------------------------------------------

function WhatStep({
  headingRef,
  answers,
  matches,
  onPickCategory,
  onUpdate,
}: {
  headingRef: React.RefObject<HTMLHeadingElement | null>;
  answers: WizardAnswers;
  matches: ReturnType<typeof templatesForCategory>;
  onPickCategory: (category: WizardAnswers["category"]) => void;
  onUpdate: (patch: Partial<WizardAnswers>) => void;
}) {
  return (
    <section className="mt-6">
      <h2
        ref={headingRef}
        tabIndex={-1}
        className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
      >
        What are you building, and who for?
      </h2>

      <fieldset className="mt-6">
        <legend className="text-sm font-medium">What kind of site is this?</legend>
        <p className="mt-1.5 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
          Kodely loads a starting brief written for that kind of business — the same ones on the{" "}
          <Link
            href="/templates"
            className="underline underline-offset-4 hover:text-neutral-900 dark:hover:text-white"
          >
            templates page
          </Link>
          . You read and edit the whole thing at the end.
        </p>
        <div className="mt-4 flex flex-wrap gap-2">
          {[...TEMPLATE_CATEGORIES, SOMETHING_ELSE].map((option) => (
            <label key={option} className="cursor-pointer">
              <input
                type="radio"
                name="wizard-category"
                value={option}
                checked={answers.category === option}
                onChange={() => onPickCategory(option)}
                className="peer sr-only"
              />
              <span className="inline-flex items-center rounded-full border border-neutral-200 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 backdrop-blur-md transition-colors hover:border-neutral-300 hover:text-neutral-900 peer-checked:border-neutral-900 peer-checked:bg-neutral-900 peer-checked:text-white peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white dark:peer-checked:border-white dark:peer-checked:bg-white dark:peer-checked:text-neutral-900">
                {option}
              </span>
            </label>
          ))}
        </div>
      </fieldset>

      {/* Only when the category holds more than one starter brief. With a
          single match it is already selected and asking would be busywork. */}
      {matches.length > 1 && (
        <fieldset className="mt-6">
          <legend className="text-sm font-medium">Which is closest?</legend>
          <div className="mt-3 flex flex-wrap gap-2">
            {matches.map((template) => (
              <label key={template.id} className="cursor-pointer">
                <input
                  type="radio"
                  name="wizard-template"
                  value={template.id}
                  checked={answers.templateId === template.id}
                  onChange={() => onUpdate({ templateId: template.id })}
                  className="peer sr-only"
                />
                <span className="inline-flex items-center rounded-full border border-neutral-200 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 transition-colors hover:border-neutral-300 hover:text-neutral-900 peer-checked:border-neutral-900 peer-checked:bg-neutral-900 peer-checked:text-white peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white dark:peer-checked:border-white dark:peer-checked:bg-white dark:peer-checked:text-neutral-900">
                  {template.name}
                </span>
              </label>
            ))}
          </div>
        </fieldset>
      )}

      <div className="mt-6 grid gap-5 sm:grid-cols-2">
        <div>
          <label htmlFor="wizard-name" className="block text-sm font-medium">
            Site or business name{" "}
            <span className="font-normal text-neutral-500 dark:text-neutral-400">(optional)</span>
          </label>
          <input
            id="wizard-name"
            type="text"
            value={answers.businessName}
            maxLength={MAX_NAME_CHARS}
            onChange={(e) => onUpdate({ businessName: e.target.value })}
            placeholder="Bloom Pilates"
            className="mt-2 w-full rounded-xl border border-black/10 bg-white px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-neutral-500 focus:border-neutral-400 focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-neutral-950 dark:placeholder:text-neutral-400 dark:focus:border-neutral-600"
          />
          <p className="mt-1.5 text-xs text-neutral-500 dark:text-neutral-400">
            Not named it yet? Leave it — the brief says [your business name] instead.
          </p>
        </div>

        <div>
          <label htmlFor="wizard-what" className="block text-sm font-medium">
            What do you actually do?{" "}
            <span className="font-normal text-neutral-500 dark:text-neutral-400">(optional)</span>
          </label>
          <input
            id="wizard-what"
            type="text"
            value={answers.whatYouDo}
            maxLength={MAX_WHAT_CHARS}
            onChange={(e) => onUpdate({ whatYouDo: e.target.value })}
            placeholder="a reformer pilates studio in Denver"
            className="mt-2 w-full rounded-xl border border-black/10 bg-white px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-neutral-500 focus:border-neutral-400 focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-neutral-950 dark:placeholder:text-neutral-400 dark:focus:border-neutral-600"
          />
          <p className="mt-1.5 text-xs text-neutral-500 dark:text-neutral-400">
            One line. It becomes the first sentence of the brief.
          </p>
        </div>
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// Step 3 — review
// ---------------------------------------------------------------------------

function ReviewStep({
  headingRef,
  promptText,
  edited,
  onEdit,
  onRevert,
  creditEstimate,
  signedIn,
  starting,
  error,
  onBuild,
}: {
  headingRef: React.RefObject<HTMLHeadingElement | null>;
  promptText: string;
  edited: string | null;
  onEdit: (next: string) => void;
  onRevert: () => void;
  creditEstimate: { low: number; high: number };
  signedIn: boolean;
  starting: boolean;
  error: string | null;
  onBuild: () => void;
}) {
  return (
    <section className="mt-6">
      <h2
        ref={headingRef}
        tabIndex={-1}
        className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
      >
        Your prompt
      </h2>
      <p className="mt-1.5 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
        This is the whole thing Kodely will build from — no hidden settings behind it. Assembled on
        your device from your answers; nothing was sent anywhere and no AI has run yet.
      </p>

      {/* The same shape as the composer's Enhance strip: a one-line note about
          where the text came from, and a Revert beside it. Accept is pressing
          Build, edit is typing, discard is Revert — no state where someone is
          looking at something they cannot change. */}
      <div className="mt-5 flex flex-wrap items-center justify-between gap-2">
        <label
          htmlFor="wizard-prompt"
          className="inline-flex items-center gap-1.5 text-xs text-neutral-500 dark:text-neutral-400"
        >
          <Sparkles size={13} aria-hidden style={{ color: "var(--accent)" }} />
          Assembled from your answers — edit anything before you build
        </label>
        {edited !== null && (
          <button
            type="button"
            onClick={onRevert}
            className="inline-flex items-center gap-1.5 rounded-md text-xs text-neutral-500 underline underline-offset-2 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:text-white"
          >
            <RotateCcw size={12} aria-hidden />
            Revert to the wizard&apos;s version
          </button>
        )}
      </div>

      <textarea
        id="wizard-prompt"
        value={promptText}
        onChange={(e) => onEdit(e.target.value)}
        rows={16}
        spellCheck={false}
        className="mt-2 w-full resize-y rounded-xl border border-black/10 bg-white p-3.5 font-mono text-[11px] leading-relaxed text-neutral-700 outline-none focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-neutral-950 dark:text-neutral-300"
      />

      {/* The one moment a credit estimate is useful rather than alarming: the
          user is about to spend, and they can still edit what they spend on. */}
      <p className="mt-3 text-xs leading-relaxed text-neutral-500 dark:text-neutral-400">
        A first build usually costs {creditEstimate.low}–{creditEstimate.high} credits. A build that
        fails to compile is never charged.
        {!signedIn && " You'll sign up first — this prompt comes with you."}
      </p>

      {error && (
        <p role="alert" className="mt-3 text-xs text-neutral-600 dark:text-neutral-400">
          {error}
        </p>
      )}

      <button
        type="button"
        onClick={onBuild}
        disabled={starting || !promptText.trim()}
        className="group mt-5 inline-flex w-full items-center justify-center gap-2 rounded-lg bg-neutral-900 px-5 py-3 text-sm font-medium text-white transition-colors hover:bg-neutral-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] disabled:pointer-events-none disabled:opacity-50 sm:w-auto dark:bg-white dark:text-neutral-900 dark:hover:bg-neutral-200"
      >
        {starting ? "Starting…" : "Build this"}
        {!starting && (
          <ArrowRight
            size={14}
            aria-hidden
            className="transition-transform group-hover:translate-x-0.5"
          />
        )}
      </button>
    </section>
  );
}

